import { useId, useMemo, useState } from 'react';
import {
  JxAlert,
  JxButton,
  JxField,
  JxInput,
  JxSelect,
  JxStack,
  JxSwitch,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const emailValid = useMemo(() => EMAIL_RE.test(email.trim()), [email]);
  const showError = touched && !emailValid;

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTouched(true);
    if (!emailValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
    setRole('viewer');
    setNotify(true);
  }

  return (
    <JxStack gap="md" style={{ maxWidth: 'var(--jx-size-form-width, 28rem)' }}>
      {invited ? (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          dismissible
          onDismiss={() => setInvited(null)}
          onClose={() => setInvited(null)}
        >
          Мы отправили приглашение на {invited}.
        </JxAlert>
      ) : null}

      <form id={formId} onSubmit={handleSubmit} noValidate>
        <JxStack gap="md">
          <JxField
            label="Рабочая почта"
            hint="Пригласим только по корпоративному адресу, например name@company.com"
            error={showError ? 'Введите адрес в формате name@company.com' : undefined}
            invalid={showError}
            required
          >
            <JxInput
              type="email"
              name="email"
              autoComplete="email"
              placeholder="name@company.com"
              value={email}
              onValueChange={setEmail}
              onBlur={() => setTouched(true)}
              invalid={showError}
            />
          </JxField>

          <JxField label="Роль в команде" hint="Роль можно изменить позже в настройках участника">
            <JxSelect
              name="role"
              value={role}
              onValueChange={(next: string) => setRole(next as Role)}
              options={ROLE_OPTIONS}
            />
          </JxField>

          <JxSwitch
            name="notify"
            label="Отправить уведомление"
            description="Участник получит письмо со ссылкой на вход"
            checked={notify}
            onCheckedChange={setNotify}
          />

          <JxButton type="submit" variant="primary" disabled={!emailValid}>
            Отправить приглашение
          </JxButton>
        </JxStack>
      </form>
    </JxStack>
  );
}

